package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Real;
    in attribute io_2 : Boolean;
    in attribute io_5 : Boolean;
    attribute showHumidity : Boolean := false;
    attribute prevPressed : Boolean := false;
    attribute pwmCountFan : Integer := 0;
    perform action tick {
      first start;
      then if io_5 and not prevPressed {
        first start;
        then assign showHumidity := (not showHumidity);
      }
      then if ((not showHumidity) and (io_2)) {
        first start;
        then assign pwmCountFan := (if io_0 > 30.0 ? (if io_0 >= 40.0 ? 255 else (if io_0 <= 30.0 ? 0 else RealFunctions::floor((io_0 - 30.0) * 25.5))) else 0);
      } else {
        first start;
        then assign pwmCountFan := (if ((io_2) and (io_0 > 30.0)) ? (if io_0 >= 40.0 ? 255 else (if io_0 <= 30.0 ? 0 else RealFunctions::floor((io_0 - 30.0) * 25.5))) else 0);
      }
      then assign prevPressed := io_5;
    }
    out attribute io_3 : Real = (if ((io_2) and (io_0 > 30.0)) ? pwmCountFan else 0.0);
    out attribute io_4 : Integer = (if showHumidity ? (if io_2 ? RealFunctions::floor(io_1) else 0) else (if io_2 ? RealFunctions::floor(io_0) else 0));
  }
  part system : Controller;
}
